const tipo = $('Extrair tipo').first().json.tipo;
const user_id = $('Extrair tipo').first().json.user_id;
const item = $input.first().json;
function extrairJSON(raw){const text=raw.output[0].content[0].text;return JSON.parse(text);}
const dados = extrairJSON(item);
const descricao = dados.descricao || dados.nome || null;
const data = dados.data || dados.vencimento || null;
const hora = dados.hora || null;
const valor = dados.valor || null;
let recorrencia = null;
if (dados.recorrencia && dados.recorrencia.padrao) {
  recorrencia = {
    padrao: dados.recorrencia.padrao,
    dias_semana: dados.recorrencia.dias_semana || null,
    dia_mes: dados.recorrencia.dia_mes || null,
    data_fim: dados.recorrencia.data_fim || null
  };
}
return [{ json: { confirmar: true, tipo, user_id, descricao, valor, data, hora, categoria: dados.categoria || null, origem: dados.origem || null, recorrencia } }];

